(()=>{
'use strict';
const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cb0';
const e=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
async function q(path,opts={}){const r=await fetch(U+path,{...opts,headers:{apikey:K,Authorization:`Bearer ${K}`,'Content-Type':'application/json',Accept:'application/json',...(opts.headers||{})}});const t=await r.text();let d=null;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw new Error(typeof d==='string'?d:(d?.message||d?.hint||`HTTP ${r.status}`));return d}
function activate(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(id)?.classList.add('active');document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'});try{window.lucide?.createIcons()}catch{}}
function wire(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>window.render?.(b.dataset.view));try{window.lucide?.createIcons()}catch{}}
function shell(k,title,desc,body){return `<div class="page suite-page"><div class="suite-kicker">${e(k)}</div><h2>${e(title)}</h2><p class="muted suite-desc">${e(desc)}</p>${body}</div>`}
function status(msg,ok=false){return `<div class="suite-status ${ok?'ok':'warn'}">${ok?'●':'!'} ${e(msg)}</div>`}
function renderReport(prefill=''){const host=$('report');if(!host)return;host.innerHTML=shell('SUARA WARGA','Laporkan Masalah di Sekitar Anda','Laporan menjadi sinyal awal dan dapat disimpan ke sistem atau perangkat bila server sedang menolak penulisan.',`<div class="card suite-panel"><div class="form-grid"><label>Judul masalah<input id="r-title" value="${e(prefill)}" placeholder="Contoh: Jalan rusak di Dusun…"></label><label>Kategori<select id="r-cat"><option>Infrastruktur</option><option>Ekonomi</option><option>Pendidikan</option><option>Kesehatan</option><option>Lingkungan</option><option>Sosial</option></select></label><label class="full">Wilayah<input id="r-region" placeholder="Desa / Kecamatan / Kabupaten / Provinsi"></label><label class="full">Cerita / deskripsi<textarea id="r-body" rows="7" placeholder="Apa masalahnya? Sejak kapan? Siapa terdampak? Bukti apa yang tersedia?"></textarea></label></div><div class="report-meta"><span>✓ Verifikasi tetap diperlukan</span><span>✓ Evidence dipisahkan dari narasi</span><span>✓ Tidak menjadi fakta otomatis</span></div><button id="r-submit" class="btn-primary">Kirim Laporan</button><div id="r-status" class="suite-status" style="display:none"></div></div>`);activate('report');wire();
$('r-submit').onclick=async()=>{const st=$('r-status'),title=$('r-title').value.trim(),body=$('r-body').value.trim(),cat=$('r-cat').value,reg=$('r-region').value.trim();st.style.display='block';if(!title||!body){st.className='suite-status warn';st.textContent='Judul dan deskripsi wajib diisi.';return}st.className='suite-status';st.textContent='Menyimpan laporan…';let region_id=null;try{if(reg){const rr=await q(`/rest/v1/regions?select=id,name&source_name=eq.BIG&name=ilike.*${encodeURIComponent(reg)}*&limit=1`);region_id=rr?.[0]?.id||null}}catch{}
const payload={title,narrative:body,category:cat,region_id,occurred_at:new Date().toISOString(),verification_status:'received',classification:'citizen_report'};
try{await q('/rest/v1/human_reports',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});st.className='suite-status ok';st.innerHTML='<b>Laporan diterima.</b> Tersimpan di sistem dan menunggu verifikasi.';localStorage.setItem('ipm_last_report',JSON.stringify({...payload,created_at:new Date().toISOString(),sync:'supabase'}));}
catch(err){const rows=JSON.parse(localStorage.getItem('ipm_reports')||'[]');rows.unshift({...payload,id:crypto.randomUUID(),region_name:reg,created_at:new Date().toISOString(),status:'received-local'});localStorage.setItem('ipm_reports',JSON.stringify(rows.slice(0,100)));st.className='suite-status warn';st.innerHTML='<b>Tersimpan sementara di perangkat.</b> Server belum menerima penulisan langsung, tetapi laporan tidak hilang.';}}}
function renderData(){const host=$('data');if(!host)return;host.innerHTML=shell('DATA & STATISTIK','Data Indonesia dalam satu tempat','Sumber, dataset, observasi, kualitas, dan cakupan wilayah ditampilkan dari basis data yang tersedia.',`<div class="suite-grid-4"><div class="suite-kpi"><span class="suite-icon">⌂</span><div><small>PROVINSI</small><b>38</b><span>registry BIG</span></div></div><div class="suite-kpi"><span class="suite-icon">▣</span><div><small>KAB/KOTA</small><b>514</b><span>registry BIG</span></div></div><div class="suite-kpi"><span class="suite-icon">▤</span><div><small>KECAMATAN</small><b>7.282</b><span>registry BIG</span></div></div><div class="suite-kpi"><span class="suite-icon">⌂</span><div><small>DESA/KEL</small><b>83.529</b><span>registry BIG</span></div></div></div><div class="suite-grid-3"><div class="card suite-panel"><h3>Sources</h3><div id="d-sources" class="suite-list"><div class="loading">Memuat…</div></div></div><div class="card suite-panel"><h3>Datasets</h3><div id="d-datasets" class="suite-list"><div class="loading">Memuat…</div></div></div><div class="card suite-panel"><h3>Observations</h3><div id="d-observations" class="suite-list"><div class="loading">Memuat…</div></div></div></div><div class="card suite-panel"><div class="suite-panel-head"><div><h3>Data Trust</h3><p>Kualitas data ditampilkan bersama sumbernya.</p></div><button class="btn-outline" id="d-refresh">Refresh</button></div><div class="trust-meter"><div class="trust-track"><i id="d-meter"></i></div><b id="d-score">—</b></div></div>`);activate('data');wire();
async function load(){try{const [s,ds,ob]=await Promise.all([q('/rest/v1/sources?select=id,name,publisher,reliability_score,active&order=name.asc&limit=8'),q('/rest/v1/datasets?select=id,name,category,quality_score,last_updated_at&order=updated_at.desc&limit=8'),q('/rest/v1/observations?select=id,metric,value_numeric,value_text,unit,observed_at,quality_score&order=observed_at.desc&limit=8')]);$('d-sources').innerHTML=s?.length?s.map(x=>`<div class="suite-row"><div><b>${e(x.name)}</b><small>${e(x.publisher||'')} · reliability ${e(x.reliability_score??'—')}</small></div><span class="pill">${x.active?'ACTIVE':'OFF'}</span></div>`).join(''):'<div class="empty">Belum ada source.</div>';$('d-datasets').innerHTML=ds?.length?ds.map(x=>`<div class="suite-row"><div><b>${e(x.name)}</b><small>${e(x.category||'')} · quality ${e(x.quality_score??'—')}</small></div><span class="pill">${x.last_updated_at?new Date(x.last_updated_at).toLocaleDateString('id-ID'):'—'}</span></div>`).join(''):'<div class="empty">Belum ada dataset.</div>';$('d-observations').innerHTML=ob?.length?ob.map(x=>`<div class="suite-row"><div><b>${e(x.metric)}</b><small>${e(x.value_numeric??x.value_text??'—')} ${e(x.unit||'')} · quality ${e(x.quality_score??'—')}</small></div><span class="pill">${x.observed_at?new Date(x.observed_at).toLocaleDateString('id-ID'):'—'}</span></div>`).join(''):'<div class="empty">Belum ada observation.</div>';const vals=[...s.map(x=>Number(x.reliability_score)),...ds.map(x=>Number(x.quality_score))].filter(Number.isFinite);const score=vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0;$('d-score').textContent=vals.length?score+'%':'Belum ada skor';$('d-meter').style.width=score+'%'}catch(err){['d-sources','d-datasets','d-observations'].forEach(id=>$(id).innerHTML=status(`Data gagal dimuat: ${err.message}`))}}$('d-refresh').onclick=load;load();}
function renderSearch(text){const host=$('result');if(!host)return;host.innerHTML=shell('PENCARIAN',`Hasil untuk “${text}”`,'Pencarian terpadu untuk wilayah dan masalah.',`<div class="card suite-panel" id="search-box"><div class="loading">Mencari…</div></div>`);activate('result');wire();const term=encodeURIComponent(text);Promise.all([q(`/rest/v1/regions?select=id,name,level,admin_code_pum&source_name=eq.BIG&name=ilike.*${term}*&limit=12`),q(`/rest/v1/problems?select=id,title,category,status,confidence,impact_score&title=ilike.*${term}*&order=updated_at.desc&limit=12`)]).then(([rs,ps])=>{$('search-box').innerHTML=`<div class="search-results"><div><h3>Wilayah</h3>${rs?.length?rs.map(x=>`<button class="suite-row suite-button" data-view="regions"><div><b>${e(x.name)}</b><small>${e(x.level)} · ${e(x.admin_code_pum||'')}</small></div><span>→</span></button>`).join(''):'<div class="empty">Tidak ditemukan wilayah.</div>'}</div><div><h3>Masalah</h3>${ps?.length?ps.map(x=>`<button class="suite-row suite-button" data-view="problems"><div><b>${e(x.title)}</b><small>${e(x.category||'Masalah')} · confidence ${e(x.confidence??'—')} · impact ${e(x.impact_score??'—')}</small></div><span>→</span></button>`).join(''):'<div class="empty">Tidak ditemukan masalah.</div>'}</div></div>`;wire()}).catch(err=>{$('search-box').innerHTML=status(`Pencarian gagal: ${err.message}`)})}
window.renderReport=renderReport;window.renderData=renderData;window.renderSearch=renderSearch;
window.render=async function(v,x=''){try{if(v==='report')return renderReport(x);if(v==='data')return renderData();if(v==='result')return renderSearch(x);const views={monitoring:'monitoring',intelligence:'intelligence',solutions:'solutions',future:'future',control:'control',account:'account',more:'more',map:'map',regions:'regions',problems:'problems'};if(views[v]&&typeof window.__IPM_BASE_RENDER==='function')return window.__IPM_BASE_RENDER(v,x);activate(v)}catch(err){const host=$(v)||$('home');if(host)host.innerHTML=shell('SYSTEM','Modul belum dapat dimuat','Kesalahan antarmuka tertangani tanpa mematikan seluruh aplikasi.',status(err.message));console.error(err)}};
})();
